CREATE TABLE IF NOT EXISTS shop_geo_dirty (shop_id BIGINT PRIMARY KEY);
CREATE TRIGGER IF NOT EXISTS shop_geo_insert AFTER INSERT ON tb_shop FOR EACH ROW INSERT IGNORE INTO shop_geo_dirty VALUES(NEW.id);
CREATE TRIGGER IF NOT EXISTS shop_geo_update AFTER UPDATE ON tb_shop FOR EACH ROW INSERT IGNORE INTO shop_geo_dirty SELECT NEW.id WHERE OLD.type_id<>NEW.type_id OR OLD.x<>NEW.x OR OLD.y<>NEW.y;
CREATE TRIGGER IF NOT EXISTS shop_geo_delete AFTER DELETE ON tb_shop FOR EACH ROW INSERT IGNORE INTO shop_geo_dirty VALUES(OLD.id);
